// LoadFailed is the package's LoadFailed in the language of msgs.
func (msgs Messages) LoadFailed(name string, error_ string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.LoadFailed(name, error_))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].LoadFailed; f != nil {
			return f(name, error_)
		}
		switch lang {
		case "", "en":
			return "Cannot show " + msgs.arg(name) + ": " + msgs.arg(error_)
		case "zh-Hans":
			return "无法显示 " + name + "：" + error_
		}
	}
}

