// PrefsSaveFailed is the package's PrefsSaveFailed in the language of msgs.
func (msgs Messages) PrefsSaveFailed(error_ string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.PrefsSaveFailed(error_))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].PrefsSaveFailed; f != nil {
			return f(error_)
		}
		switch lang {
		case "", "en":
			return "Cannot save preferences: " + msgs.arg(error_)
		case "zh-Hans":
			return "无法保存设置：" + error_
		}
	}
}

